@import "@fontsource-variable/inter";
@import "@fontsource-variable/newsreader";
@import "@fontsource/space-mono/400.css";

/* Light (faithful): white page, #f3f3f7 grey bands and cards, #f9f9fb hero, #e5e6f0 lavender
   illustration panels, ink #15191e with #60646c secondary text, hairlines a blue-grey at 15%,
   vermilion #ff3d00 for every action (hover #ff6b18). */
:root {
  --background: #ffffff;
  --foreground: #15191e;
  --card: #ffffff;
  --card-foreground: #15191e;
  --popover: #ffffff;
  --popover-foreground: #15191e;
  --primary: #ff3d00;
  --primary-foreground: #fcfcfd;
  --secondary: #f9f9fb;
  --secondary-foreground: #15191e;
  --muted: #f3f3f7;
  --muted-foreground: #60646c;
  --accent: #e5e6f0;
  --accent-foreground: #15191e;
  --destructive: #d92d20;
  --destructive-foreground: #ffffff;
  --border: rgb(66 87 138 / 15%);
  --input: rgb(66 87 138 / 22%);
  --ring: #ff6b18;
  --highlight: #ff6b18;
  --highlight-foreground: #15191e;
  --glow: #ffb258;
  --chart-1: #ff3d00;
  --chart-2: #3b93ff;
  --chart-3: #4b2fd0;
  --chart-4: #1f8a3a;
  --chart-5: #ffb258;
  --sidebar: #f9f9fb;
  --sidebar-foreground: #15191e;
  --sidebar-primary: #ff3d00;
  --sidebar-primary-foreground: #fcfcfd;
  --sidebar-accent: #f3f3f7;
  --sidebar-accent-foreground: #15191e;
  --sidebar-border: rgb(66 87 138 / 15%);
  --sidebar-ring: #ff6b18;

  --typeface-body: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Inter Variable", ui-sans-serif, system-ui, sans-serif;
  /* quotes only: blocks read it as var(--typeface-serif, Georgia) so other themes fall back */
  --typeface-serif: "Newsreader Variable", Georgia, serif;
  --typeface-mono: "Space Mono", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 90rem;
  --page-gutter: 1.5rem;
  --section-y: 4rem;
}

/* Dark sibling: the original's near-black blue (#000710) as the page, deeper blue-greys for
   panels, the same orange. */
.dark {
  --background: #000710;
  --foreground: #fcfcfd;
  --card: #0b121c;
  --card-foreground: #fcfcfd;
  --popover: #0b121c;
  --popover-foreground: #fcfcfd;
  --primary: #ff3d00;
  --primary-foreground: #fcfcfd;
  --secondary: #070e18;
  --secondary-foreground: #fcfcfd;
  --muted: #101823;
  --muted-foreground: #b9bbc6;
  --accent: #1a2230;
  --accent-foreground: #fcfcfd;
  --destructive: #f0584c;
  --destructive-foreground: #ffffff;
  --border: rgb(255 255 255 / 12%);
  --input: rgb(255 255 255 / 18%);
  --ring: #ff6b18;
  --highlight: #ff6b18;
  --highlight-foreground: #15191e;
  --glow: #ff8a3d;
  --chart-1: #ff3d00;
  --chart-2: #5aa6ff;
  --chart-3: #8a76ff;
  --chart-4: #3ec165;
  --chart-5: #ffb258;
  --sidebar: #070e18;
  --sidebar-foreground: #fcfcfd;
  --sidebar-primary: #ff3d00;
  --sidebar-primary-foreground: #fcfcfd;
  --sidebar-accent: #1a2230;
  --sidebar-accent-foreground: #fcfcfd;
  --sidebar-border: rgb(255 255 255 / 12%);
  --sidebar-ring: #ff6b18;
}
